mapper.select:
AND oper_ip like concat('%', #{operIp}, '%')
AND title like concat('%', #{title}, '%')
AND resource_code like concat('%', #{resourceCode}, '%') AND oper_location like concat('%', #{operLocation}, '%') AND (method like concat('%', #{method}, '%') OR request_method like concat('%', #{method}, '%')) AND oper_url like concat('%', #{operUrl}, '%') AND request_headers like concat('%', #{requestHeaders}, '%') AND query_string like concat('%', #{queryString}, '%') AND request_params like concat('%', #{requestParams}, '%') AND request_body like concat('%', #{requestBody}, '%')
AND business_type = #{businessType}
AND business_type in
#{businessType}
AND status = #{status}
AND oper_name like concat('%', #{operName}, '%')
AND oper_time >= #{params.beginTime}
AND oper_time <= #{params.endTime}
order by oper_id desc
